```python
import re

# pattern for commas
pattern = re.compile(r',\s*')
# pattern for letters
pattern = re.compile(r'[a-zA-Z]+\s*')
# pattern for odd commas
pattern = re.compile(r',\s+')
# pattern for odd letters
pattern = re.compile(r'[a-z]+')

def check_if_has_no_commas(txt):
    if pattern.match(txt):
        return []
    # check if there are no commas
    if len(pattern.findall(txt)) == 0:
        return []
    # check if there are no letters with odd order
    if pattern.findall(txt)[0].islower():
        letters = set()
        for letter in pattern.findall(txt)[0].lower():
            if letter.islower():
                letters.add(letter)
        return pattern.findall(txt)[0].lower()
    # check if there are no letters with even order
    if pattern.findall(txt)[0].islower():
        return pattern.findall(txt)[0].lower()
    return pattern.findall(txt)[0].lower()

def check_if_has_no_letters(txt):
    # check if there are no letters
    if pattern.match(txt):
        return []
    # check if there are no letters with odd order
    if pattern.findall(txt)[0].islower():
        letters = set()
        for letter in pattern.findall(txt)[0].lower():
            if letter.islower():
                letters.add(letter)
        return pattern.findall(txt)[0].lower()
    # check if there are no letters with even order
    if pattern.findall(txt)[0].islower():
        return pattern.findall(txt)[0].lower()
    return pattern.findall(txt)[0].lower()

if __name__ == '__main__':
