def tri(n):
    if n == 1:
        return [1]
    if n % 2 == 0:
        return tri(n // 2) + [tri(n // 2)]
    else:
        return tri(n // 2) + tri(n - 1) + tri(n // 2)

def tri_count(n):
    if n == 1:
        return 1
    if n % 2 == 0:
        return 1
    else:
        return tri_count(n // 2) + tri_count(n - 1) + tri_count(n // 2)

def main():
    n = int(input("Enter a positive integer: "))
    if n < 1:
        print("Error: n must be greater than 0")
    else:
        if n == 1:
            print(tri(n))
        else:
            print(tri_count(n))

if __name__ == "__main__":
