```python
def sum_of_squares(lst):
    sum = 0
    for I in range(len(lst)):
        if I % 3 == 0 and I % 4 != 0:
            sum += lst[i]**2
        elif I % 3 == 0 and I % 4 == 0:
            sum += lst[i]**3
        elif I % 3 != 0 and I % 4 != 0:
            sum += lst[i]**4
        else:
            sum += lst[i]
    return sum
```

