from collections import Counter

def get_extension(extensions: list[str], threshold: float) -> str:
    if len(extensions) == 0:
        return ''
    if len(extensions) == 1:
        return extensions[0]
    strength = 0
    for extension in extensions:
        strength += len(extension.upper()) - len(extension.lower())
    if strength == 0:
        return ''
    strength = max(strength, 0)
    last_extension = extensions[-1]
    for extension in extensions:
        if extension.upper() == extension.lower():
            strength -= len(extension.upper())
    if strength > 0:
        return last_extension.lower()
    else:
        return last_extension.upper()

def check_similarity(extensions: list[str], threshold: float) -> str:
    counter = Counter(extensions)
    for key, val in counter.items():
        if val > threshold:
            return key.lower()
    return ''

