def prime_fib(n):
    if n <= 1:
        return n
    if n % 2 == 0:
        return n
    if n % 3 == 0:
        return n
    if n % 5 == 0:
        return n
    return prime_fib(n-1) + prime_fib(n-2)

def has_close_elements(numbers, threshold):
    if any(numbers > threshold):
        return False
    if all(numbers <= threshold):
        return True
    return has_close_elements(numbers[:-1], threshold)

def main():
    numbers = [1.0, 2.8, 3.0, 4.0, 5.0, 2.0]
    threshold = 2.0
    result = prime_fib(len(numbers))
    print(f'The number of prime numbers less than {threshold} in the list is {result}.')

if __name__ == '__main__':
    main()
```

