def sum_product(numbers: list) -> Tuple[int, int]:
    """
    Return the sum and product of the numbers in the given list.
    """
    if not numbers:
        return (0, 1)
    sum = 0
    product = 1
    for num in numbers:
        sum += num
        product *= num
    return (sum, product)
